class FormulaTranslator
{
    private const QUOTED_SHEET_NAME = '\'(?:[^\']|\'\')*\'';

    private const UNQUOTED_SHEET_NAME = '[^\'.]+';

    private const SHEET_REFERENCE = '\$?(?:\'((?:[^\']|\'\')*)\'|([^\'.]+))\.';

    public static function convertToExcelAddressValue(string $openOfficeAddress): string
    {
        $excelAddress = (string) preg_replace_callback(
            [
                '/' . self::SHEET_REFERENCE . '([^:\.]+):\$?(?:' . self::QUOTED_SHEET_NAME . '|' . self::UNQUOTED_SHEET_NAME . ')\.([^:\.]+)/miu', // Cell range 3-d reference
                '/' . self::SHEET_REFERENCE . '([^:\.]+):\.([^:\.]+)/miu', // Cell range reference in another sheet
                '/' . self::SHEET_REFERENCE . '([^:\.]+)/miu', // Cell reference in another sheet
                '/\.([^:\.]+):\.([^:\.]+)/miu', // Cell range reference
                '/\.([^:\.]+)/miu', // Simple cell reference
            ],
            [self::class, 'convertAddressMatch'],
            $openOfficeAddress
        );

        return $excelAddress;
    }

    private static function convertAddressMatch(array $matches): string
    {
        if (($matches[4] ?? '') !== '') {
            // Cell range 3-d reference - as we don't support 3-d ranges, we're just
            // going to take a quick and dirty approach and assume that the second
            // worksheet reference is the same as the first
            return self::composeSheetReference($matches[1] ?? '', $matches[2] ?? '')
                . $matches[3] . ':' . $matches[4];
        }
        if (($matches[8] ?? '') !== '') {
            // Cell range reference in another sheet
            return self::composeSheetReference($matches[5] ?? '', $matches[6] ?? '')
                . $matches[7] . ':' . $matches[8];
        }
        if (($matches[11] ?? '') !== '') {
            // Cell reference in another sheet
            return self::composeSheetReference($matches[9] ?? '', $matches[10] ?? '') . $matches[11];
        }
        if (($matches[13] ?? '') !== '') {
            // Cell range reference
            return $matches[12] . ':' . $matches[13];
        }

        // Simple cell reference
        return $matches[14] ?? '';
    }

    private static function composeSheetReference(string $quotedSheetName, string $unquotedSheetName): string
    {
        return $quotedSheetName . $unquotedSheetName . '!';
    }

    public static function convertToExcelFormulaValue(string $openOfficeFormula): string
    {
        $temp = explode(Calculation::FORMULA_STRING_QUOTE, $openOfficeFormula);
        $tKey = false;
        $inMatrixBracesLevel = 0;
        $inFunctionBracesLevel = 0;
        foreach ($temp as &$value) {
            // @var string $value
            // Only replace in alternate array entries (i.e. non-quoted blocks)
            //      so that conversion isn't done in string values
            $tKey = $tKey === false;
            if ($tKey) {
                $value = (string) preg_replace(
                    [
                        '/\[\$?([^\.]+)\.([^\.]+):\.([^\.]+)\]/miu', // Cell range reference in another sheet
                        '/\[\$?([^\.]+)\.([^\.]+)\]/miu', // Cell reference in another sheet
                        '/\[\.([^\.]+):\.([^\.]+)\]/miu', // Cell range reference
                        '/\[\.([^\.]+)\]/miu', // Simple cell reference
                    ],
                    [
                        '$1!$2:$3',
                        '$1!$2',
                        '$1:$2',
                        '$1',
                    ],
                    $value
                );
                // Convert references to defined names/formulae
                $value = str_replace('$$', '', $value);

                // Convert ODS function argument separators to Excel function argument separators
                $value = Calculation::translateSeparator(';', ',', $value, $inFunctionBracesLevel);

                // Convert ODS matrix separators to Excel matrix separators
                $value = Calculation::translateSeparator(
                    ';',
                    ',',
                    $value,
                    $inMatrixBracesLevel,
                    Calculation::FORMULA_OPEN_MATRIX_BRACE,
                    Calculation::FORMULA_CLOSE_MATRIX_BRACE
                );
                $value = Calculation::translateSeparator(
                    '|',
                    ';',
                    $value,
                    $inMatrixBracesLevel,
                    Calculation::FORMULA_OPEN_MATRIX_BRACE,
                    Calculation::FORMULA_CLOSE_MATRIX_BRACE
                );

                $value = (string) preg_replace('/COM\.MICROSOFT\./ui', '', $value);
            }
        }

        // Then rebuild the formula string
        $excelFormula = implode('"', $temp);

